/**
 * Rules engine: type chart + damage formula.
 *
 * Damage formula (exact, integer math at each step):
 *   damage = floor(floor(floor(2*Level/5 + 2) * Power * Atk / Def) / 50) + 2
 * then STAB x1.5 with floor after multiply, then type effectiveness multiplier
 * with floor after multiply.
 */

export type ElementType = "fire" | "water" | "grass";

/** Attacker element -> defender element -> multiplier. */
export const TYPE_CHART: Record<ElementType, Record<ElementType, number>> = {
  fire: { fire: 0.5, water: 0.5, grass: 2.0 }, // fire weak vs water, strong vs grass
  water: { fire: 2.0, water: 0.5, grass: 0.5 }, // water strong vs fire, weak vs grass
  grass: { fire: 0.5, water: 2.0, grass: 0.5 }, // grass strong vs water, weak vs fire
};

export function typeEffectiveness(attack: ElementType, defend: ElementType): number {
  return TYPE_CHART[attack][defend];
}

export interface DamageInput {
  level: number;
  power: number;
  attack: number;
  defense: number;
  /** True if the move's type matches one of the attacker's types. */
  stab?: boolean;
  attackType: ElementType;
  defenderType: ElementType;
}

export interface DamageBreakdown {
  baseDamage: number;
  afterStab: number;
  afterType: number;
  total: number;
}

export function computeDamage(input: DamageInput): DamageBreakdown {
  const { level, power, attack, defense } = input;

  // damage = floor(floor(floor(2*Level/5 + 2) * Power * Atk / Def) / 50) + 2
  const levelTerm = Math.floor((2 * level) / 5) + 2;
  const inner = Math.floor((levelTerm * power * attack) / defense);
  const baseDamage = Math.floor(inner / 50) + 2;

  // STAB x1.5, floor after multiply.
  let dmg = input.stab ? Math.floor(baseDamage * 1.5) : baseDamage;
  const afterStab = dmg;

  // Type chart multiplier, floored so we stay in integer HP land.
  const eff = typeEffectiveness(input.attackType, input.defenderType);
  dmg = Math.floor(dmg * eff);
  const afterType = dmg;

  return { baseDamage, afterStab, afterType, total: dmg };
}

