import { computeDamage, type ElementType } from "./rules.js";

/** Deterministic seeded PRNG (mulberry32). */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface Move {
  name: string;
  type: ElementType;
  power: number;
}

export interface Monster {
  name: string;
  type: ElementType;
  level: number;
  maxHp: number;
  hp: number;
  attack: number;
  defense: number;
  speed: number;
  move: Move;
  /** Whether the move matches the monster's own type (STAB). */
  stab?: boolean;
}

export interface TurnEvent {
  turn: number;
  actor: string;
  target: string;
  damage: number;
  /** Target HP after the hit. */
  targetHpAfter: number;
  /** True if the actor won the speed check (or coin flip on tie). */
  actedFirst: boolean;
  speedTie: boolean;
}

export interface BattleLogEntry extends TurnEvent {
  attackerHpAfter: number;
  defenderHpAfter: number;
}

export interface BattleResult {
  winner: string;
  turns: BattleLogEntry[];
}

/**
 * One round: both monsters act, ordered by Speed (higher first).
 * On a Speed tie, a seeded coin flip decides order.
 * Battle ends early when a monster faints; it does not act back.
 */
export function resolveTurn(a: Monster, b: Monster, turn: number, rng: () => number): BattleLogEntry[] {
  const tie = a.speed === b.speed;
  const coinHeads = rng() < 0.5; // heads => `first` goes first
  let first: Monster;
  let second: Monster;
  if (tie) {
    first = coinHeads ? a : b;
    second = coinHeads ? b : a;
  } else {
    first = a.speed > b.speed ? a : b;
    second = a.speed > b.speed ? b : a;
  }

  const events: BattleLogEntry[] = [];
  const strike = (actor: Monster, target: Monster, actedFirst: boolean): void => {
    if (actor.hp <= 0) return; // fainted mons don't act
    const dmg = computeDamage({
      level: actor.level,
      power: actor.move.power,
      attack: actor.attack,
      defense: target.defense,
      stab: actor.stab ?? actor.move.type === actor.type,
      attackType: actor.move.type,
      defenderType: target.type,
    }).total;
    target.hp = Math.max(0, target.hp - dmg);
    events.push({
      turn,
      actor: actor.name,
      target: target.name,
      damage: dmg,
      targetHpAfter: target.hp,
      actedFirst,
      speedTie: tie,
      attackerHpAfter: actor.hp,
      defenderHpAfter: target.hp,
    });
  };

  strike(first, second, true);
  strike(second, first, false); // skipped automatically if second fainted
  return events;
}

/** Scripted battle to the end (max `maxTurns` safety cap). */
export function runBattle(
  a: Monster,
  b: Monster,
  seed: number,
  maxTurns = 100
): BattleResult {
  const rng = mulberry32(seed);
  // Work on copies so caller state is untouched.
  const x: Monster = { ...a, move: { ...a.move }, hp: a.maxHp };
  const y: Monster = { ...b, move: { ...b.move }, hp: b.maxHp };
  x.hp = a.maxHp;
  y.hp = b.maxHp;

  const turns: BattleLogEntry[] = [];
  for (let t = 1; t <= maxTurns; t++) {
    if (x.hp <= 0 || y.hp <= 0) break;
    turns.push(...resolveTurn(x, y, t, rng));
    if (x.hp <= 0 || y.hp <= 0) break;
  }
  const winner = x.hp > 0 ? x.name : y.name;
  return { winner, turns };
}

