import { describe, it, expect } from "vitest";
import { computeDamage, typeEffectiveness, TYPE_CHART } from "../src/rules.js";

describe("type chart", () => {
  it("fire/water/grass triangle: 2.0 strong, 0.5 weak, 1.0 neutral", () => {
    // Strong (2.0)
    expect(typeEffectiveness("fire", "grass")).toBe(2.0);
    expect(typeEffectiveness("water", "fire")).toBe(2.0);
    expect(typeEffectiveness("grass", "water")).toBe(2.0);

    // Weak (0.5)
    expect(typeEffectiveness("fire", "water")).toBe(0.5);
    expect(typeEffectiveness("water", "grass")).toBe(0.5);
    expect(typeEffectiveness("grass", "fire")).toBe(0.5);

    // Neutral (1.0) — same-type matchups
    expect(typeEffectiveness("fire", "fire")).toBe(1.0);
    expect(typeEffectiveness("water", "water")).toBe(1.0);
    expect(typeEffectiveness("grass", "grass")).toBe(1.0);
  });

  it("chart is fully defined with only 2.0 / 0.5 / 1.0 values", () => {
    for (const atk of Object.keys(TYPE_CHART) as Array<keyof typeof TYPE_CHART>) {
      for (const def of Object.keys(TYPE_CHART.fire) as Array<keyof typeof TYPE_CHART>) {
        expect([2.0, 1.0, 0.5]).toContain(TYPE_CHANT_SAFE(atk, def));
      }
    }
  });

  function TYPE_CHANT_SAFE(a: keyof typeof TYPE_CHART, d: keyof typeof TYPE_CHART): number {
    return TYPE_CHART[a][d];
  }
});

describe("damage formula vectors", () => {
  const base = { level: 50, power: 80, attack: 100, defense: 100 };

  it("base damage = 37 (no STAB, neutral type)", () => {
    // floor(2*50/5+2)=22; floor(22*80*100/100)=1760; floor(1760/50)=35; +2=37
    const r = computeDamage({ ...base, attackType: "fire", defenderType: "fire" });
    expect(r.baseDamage).toBe(37);
    expect(r.afterStab).toBe(37); // no STAB applied
    expect(r.total).toBe(37); // fire vs fire = 1.0
  });

  it("with STAB = 55 (floor after multiply: floor(37 * 1.5))", () => {
    const r = computeDamage({ ...base, stab: true, attackType: "water", defenderType: "water" });
    expect(r.baseDamage).toBe(37);
    expect(r.afterStab).toBe(55);
    expect(r.total).toBe(55); // water vs water = 1.0
  });

  it("STAB + super-effective = 110 (floor(55 * 2))", () => {
    const r = computeDamage({ ...base, stab: true, attackType: "fire", defenderType: "grass" });
    expect(r.baseDamage).toBe(37);
    expect(r.afterStab).toBe(55);
    expect(r.total).toBe(110);
  });

  it("integer flooring happens at every step, not just the end", () => {
    // Level 7: floor(14/5)+2 = 4; power 30, atk 33, def 40:
    // floor(4*30*33/40)=floor(3960/40)=99 -> wait, use odd numbers to force truncation.
    const r = computeDamage({ level: 7, power: 31, attack: 37, defense: 45, attackType: "grass", defenderType: "fire" });
    const levelTerm = Math.floor((2 * 7) / 5) + 2; // floor(2.8)+2 = 4
    const inner = Math.floor((levelTerm * 31 * 37) / 45); // floor(4588/45) = 101
    const expectedBase = Math.floor(inner / 50) + 2; // floor(101/50)+2 = 4
    expect(r.baseDamage).toBe(expectedBase);
    expect(r.total).toBe(Math.floor(expectedBase * 0.5)); // grass vs fire = 0.5 -> floor(4/2)=2
  });
