  const base = { level: 50, power: 80, attack: 100, defense: 100 };

  it("base damage = 37 (no STAB, neutral type)", () => {
    // floor(2*50/5+2)=22; floor(22*80*100/100)=1760; floor(1760/50)=35; +2=37
    const r = computeDamage({ ...base, attackType: "fire", defenderType: "fire" });
    expect(r.baseDamage).toBe(37);
    expect(r.afterStab).toBe(37); // no STAB applied
    expect(r.total).toBe(37); // fire vs fire = 1.0
  });

