import { describe, it, expect } from "vitest";
import {
  runBattle,
  resolveTurn,
  mulberry32,
  type Monster,
  type Move,
} from "../src/battle.js";

const EMBER: Move = { name: "Ember", type: "fire", power: 80 };
const AQUA_JET: Move = { name: "Aqua Jet", type: "water", power: 80 };

function charmander(speed = 65): Monster {
  return {
    name: "Cinder",
    type: "fire",
    level: 50,
    maxHp: 200,
    hp: 200,
    attack: 100,
    defense: 100,
    speed,
    move: EMBER,
    stab: true,
  };
}

function squirtle(speed = 60): Monster {
  return {
    name: "Splashy",
    type: "water",
    level: 50,
    maxHp: 200,
    hp: 200,
    attack: 100,
    defense: 100,
    speed,
    move: AQUA_JET,
    stab: true,
  };
}

describe("turn resolution", () => {
  it("higher Speed acts first", () => {
    const rng = mulberry32(1);
    const events = resolveTurn(charmander(90), squirtle(40), 1, rng);
    expect(events.map((e) => e.actor)).toEqual(["Cinder", "Splashy"]);
    expect(events[0]?.actedFirst).toBe(true);
    expect(events[0]?.speedTie).toBe(false);
  });

  it("speed ties are broken by the seeded coin (deterministic)", () => {
    const a = charmander(70);
    const b = squirtle(70);

    // Same seed -> identical order.
    const r1 = runBattle(a, b, 42);
    const r2 = runBattle(a, b, 42);
    expect(r1.turns.map((e) => [e.actor, e.targetHpAfter])).toEqual(
      r2.turns.map((e) => [e.actor, e.targetHpAfter])
    );

    // The coin was actually consulted: first actor is decided by coinHeads.
    // mulberry32(42)() determines it; verify against a manual roll.
    expect(r1.turns[0]?.speedTie).toBe(true);
    const manualCoin = mulberry32(42)();
    const expectedFirst = manualCoin < 0.5 ? "Cinder" : "Splashy";
    expect(r1.turns[0]?.actor).toBe(expectedFirst);
  });

  it("a fainted monster does not strike back in the same turn", () => {
    const fast = charmander(99);
    const slow = { ...squirtle(10), maxHp: 110, hp: 110 }; // dies to one hit
    const events = resolveTurn(fast, slow, 1, mulberry32(7));
    expect(events).toHaveLength(1); // only the KO hit
    expect(events[0]?.targetHpAfter).toBe(0);
  });
});

describe("scripted battle: exact turn-by-turn HP log", () => {
  it("produces the exact expected log and winner", () => {
    const result = runBattle(charmander(), squirtle(), 1234);

    // Hand-computed damage values:
    // Cinder (fire STAB) vs Splashy (water): eff 0.5 -> floor(floor(37*1.5)*0.5) = floor(55*0.5)=27
    // Splashy (water STAB) vs Cinder (fire): eff 2.0 -> floor(55*2)=110
    // Speeds 65 vs 60: Cinder always acts first. No coin needed (no tie).
    const expectedLog = [
      { turn: 1, actor: "Cinder", target: "Splashy", damage: 27, targetHpAfter: 173 },
      { turn: 1, actor: "Splashy", target: "Cinder", damage: 110, targetHpAfter: 90 },
      { turn: 2, actor: "Cinder", target: "Splashy", damage: 27, targetHpAfter: 146 },
      { turn: 2, actor: "Splashy", target: "Cinder", damage: 110, targetHpAfter: -20 },
    ];

    expect(result.winner).toBe("Splashy");
    expect(result.turns).toHaveLength(4);
    for (let i = 0; i < expectedLog.length; i++) {
      const got = result.turns[i];
      const want = expectedLog[i]!;
      expect(got.actor).toBe(want.actor);
      expect(got.target).toBe(want.target);
      expect(got.turn).toBe(want.turn);
      expect(got.damage).toBe(want.damage);
      expect(got.targetHpAfter).toBe(Math.max(0, want.targetHpAfter));
      if (i % 2 === 0) {
        // attacker HP unchanged on the opening strike of each turn
        expect(got.attackerHpAfter).toBe([200, 200, 90, 90][Math.floor(i / 2)]!);
      } else {
        // defender's HP equals the previous event's target HP
        expect(got.attackerHpAfter).toBe(result.turns[i - 1]!.targetHpAfter);
      }
    }

    // Exact HP trajectory as flat tuples: [actorHP, targetHP] after each event.
    expect(
      result.turns.map((e) => [e.actor, e.attackerHpAfter, e.defenderHpAfter])
    ).toEqual([
      ["Cinder", 200, 173],
      ["Splashy", 173, 90],
      ["Cinder", 90, 146],
      ["Splashy", 146, 0],
    ]);
  });

  it("seeded coin changes nothing when speeds differ (same log across seeds)", () => {
    const s1 = runBattle(charmander(), squirtle(), 1);
    const s2 = runBattle(charmander(), squirtle(), 999);
    expect(s1.turns).toEqual(s2.turns);
  });

  it("speed tie + seed produces a deterministic alternate script", () => {
    const a = charmander(70);
    const b = squirtle(70);
    const r = runBattle(a, b, 5);
    // Damage per hit is still deterministic: 27 or 110 depending on matchup.
    expect(new Set(r.turns.map((e) => e.damage))).toEqual(new Set([27, 110]));
    expect(r.turns.every((e) => e.speedTie)).toBe(false === true ? false : true || true ? true : false); // all tie
    expect(r.turns.every((e) => e.speedTie)).toBe(true);
    // Winner depends only on order; both scripts end with Splashy winning
    // because Splashy deals 110/hit vs Cinder's 27/hit regardless of who goes first.
    expect(r.winner).toBe("Splashy");
    expect(r.turns.at(-1)?.targetHpAfter).toBe(0);
  });

  it("battle state copies are not mutated by runBattle", () => {
    const a = charmander();
    const b = squirtle();
    runBattle(a, b, 31337);
    expect(a.hp).toBe(200);
    expect(b.hp).toBe(200);
  });
});

